#include "fs_internal.h"
#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <inttypes.h>
static pthread_mutex_t meta=PTHREAD_MUTEX_INITIALIZER;
static open_file_t oft[MAX_OPEN_FILES];
static superblock_t sb;
static int mounted;
int inode_read(uint32_t n,inode_t *o){if(n>=NUM_INODES||!o)return -EINVAL;unsigned char b[BLOCK_SIZE];disk_read(2+n/8,b);memcpy(o,b+(n%8)*64,64);return 0;}
int inode_write(uint32_t n,const inode_t *in){if(n>=NUM_INODES||!in)return -EINVAL;unsigned char b[BLOCK_SIZE];disk_read(2+n/8,b);memcpy(b+(n%8)*64,in,64);return disk_write(2+n/8,b);}
int map_block(inode_t *x,uint32_t l,int create){if(l>=138)return -EFBIG;if(l<10){if(!x->direct[l]&&create){int b=alloc_block();if(b<0)return b;x->direct[l]=(uint32_t)b;x->block_count++;}return x->direct[l]?(int)x->direct[l]:-ENOENT;} if(!x->indirect&&create){int b=alloc_block();if(b<0)return b;x->indirect=(uint32_t)b;x->block_count++;unsigned z[128]={0};disk_write(x->indirect,z);} if(!x->indirect)return -ENOENT;uint32_t a[128];disk_read(x->indirect,a);unsigned k=l-10;if(!a[k]&&create){int b=alloc_block();if(b<0)return b;a[k]=(uint32_t)b;x->block_count++;disk_write(x->indirect,a);}return a[k]?(int)a[k]:-ENOENT;}
static int count_free_blocks(void){unsigned char b[512];disk_read(1,b);int n=0;for(int i=DATA_START;i<NUM_BLOCKS;i++)if(!(b[i/8]&(1<<(i%8))))n++;return n;}
int fs_format(void){pthread_mutex_lock(&meta);disk_zero();memset(&sb,0,sizeof sb);sb.magic=FS_MAGIC;sb.block_count=NUM_BLOCKS;sb.inode_count=NUM_INODES;sb.free_inodes=NUM_INODES-1;unsigned char bm[512]={0};for(int i=0;i<DATA_START;i++)bm[i/8]|=1u<<(i%8);disk_write(1,bm);disk_write(0,&sb);inode_t root={0};root.type=INODE_DIR;root.permissions=0755;int b=alloc_block();root.direct[0]=(uint32_t)b;root.block_count=1;inode_write(0,&root);dir_entry_t e[16]={0};strcpy(e[0].name,".");e[0].inode_no=0;strcpy(e[1].name,"..");e[1].inode_no=0;disk_write((uint32_t)b,e);mounted=1;memset(oft,0,sizeof oft);pthread_mutex_unlock(&meta);return 0;}
int fs_mount(void){pthread_mutex_lock(&meta);disk_read(0,&sb);if(sb.magic!=FS_MAGIC){pthread_mutex_unlock(&meta);return -EINVAL;}mounted=1;memset(oft,0,sizeof oft);pthread_mutex_unlock(&meta);return 0;}
int fs_unmount(void){pthread_mutex_lock(&meta);mounted=0;memset(oft,0,sizeof oft);pthread_mutex_unlock(&meta);return 0;}
uint32_t fs_root_inode(void){return 0;}
static int create_common(const char *path,uint16_t user,uint32_t cwd,int type){uint32_t found,par;char leaf[29];int r=resolve_path(path,cwd,&found,&par,leaf);if(r==0)return -EEXIST;if(r!=-ENOENT)return r;if(!leaf[0])return -EINVAL;uint32_t check;if(dir_lookup(par,leaf,&check)==0)return -EEXIST;int n=alloc_inode(type,user);if(n<0)return n;inode_t x;inode_read((uint32_t)n,&x);if(type==INODE_DIR){int b=alloc_block();if(b<0){free_inode(n);return b;}x.direct[0]=(uint32_t)b;x.block_count=1;dir_entry_t e[16]={0};strcpy(e[0].name,".");e[0].inode_no=n;strcpy(e[1].name,"..");e[1].inode_no=par;disk_write((uint32_t)b,e);}inode_write((uint32_t)n,&x);r=dir_add(par,leaf,(uint32_t)n);if(r<0){for(int i=0;i<10;i++)if(x.direct[i])free_block(x.direct[i]);free_inode(n);}return r;}
int fs_create(const char *p,uint16_t u,uint32_t c){pthread_mutex_lock(&meta);int r=create_common(p,u,c,INODE_FILE);pthread_mutex_unlock(&meta);return r;}
int fs_mkdir(const char *p,uint32_t c){pthread_mutex_lock(&meta);int r=create_common(p,0,c,INODE_DIR);pthread_mutex_unlock(&meta);return r;}
int fs_cd(const char *p,uint32_t c){pthread_mutex_lock(&meta);uint32_t n;int r=resolve_path(p,c,&n,NULL,NULL);if(r==0){inode_t x;inode_read(n,&x);if(x.type!=INODE_DIR)r=-ENOTDIR;else r=(int)n;}pthread_mutex_unlock(&meta);return r;}
int fs_open(const char *p,int mode,uint32_t c){pthread_mutex_lock(&meta);uint32_t n;int r=resolve_path(p,c,&n,NULL,NULL);if(r==0){inode_t x;inode_read(n,&x);if(x.type!=INODE_FILE)r=-EISDIR;else{r=-EMFILE;for(int i=0;i<MAX_OPEN_FILES;i++)if(!oft[i].used){oft[i]=(open_file_t){n,0,mode,1};r=i;break;}}}pthread_mutex_unlock(&meta);return r;}
int fs_close(int fd){if(fd<0||fd>=MAX_OPEN_FILES)return -EBADF;pthread_mutex_lock(&meta);if(!oft[fd].used){pthread_mutex_unlock(&meta);return -EBADF;}oft[fd].used=0;pthread_mutex_unlock(&meta);return 0;}
ssize_t fs_read(int fd,void *buf,size_t n,uint32_t off){if(fd<0||fd>=MAX_OPEN_FILES||!buf)return -EBADF;pthread_mutex_lock(&meta);if(!oft[fd].used){pthread_mutex_unlock(&meta);return -EBADF;}inode_t x;inode_read(oft[fd].inode_no,&x);if(off>=x.size){pthread_mutex_unlock(&meta);return 0;}if(n>x.size-off)n=x.size-off;size_t done=0;while(done<n){uint32_t pos=off+(uint32_t)done,l=pos/512,bo=pos%512;size_t take=512-bo;if(take>n-done)take=n-done;int b=map_block(&x,l,0);if(b<0){pthread_mutex_unlock(&meta);return done?(ssize_t)done:b;}unsigned char tmp[512];disk_read((uint32_t)b,tmp);memcpy((char*)buf+done,tmp+bo,take);done+=take;}oft[fd].offset=off+(uint32_t)done;pthread_mutex_unlock(&meta);return (ssize_t)done;}
ssize_t fs_write(int fd,const void *buf,size_t n,uint32_t off){if(fd<0||fd>=MAX_OPEN_FILES||!buf)return -EBADF;if(off>FS_MAX_FILE_SIZE || n>FS_MAX_FILE_SIZE-off)return -EFBIG;pthread_mutex_lock(&meta);if(!oft[fd].used){pthread_mutex_unlock(&meta);return -EBADF;}inode_t x;inode_read(oft[fd].inode_no,&x);size_t done=0;while(done<n){uint32_t pos=off+(uint32_t)done,l=pos/512,bo=pos%512;size_t take=512-bo;if(take>n-done)take=n-done;int b=map_block(&x,l,1);if(b<0){inode_write(oft[fd].inode_no,&x);pthread_mutex_unlock(&meta);return done?(ssize_t)done:b;}unsigned char tmp[512];if(bo||take<512)disk_read((uint32_t)b,tmp);else memset(tmp,0,512);memcpy(tmp+bo,(const char*)buf+done,take);disk_write((uint32_t)b,tmp);done+=take;}if(off+done>x.size)x.size=off+(uint32_t)done;inode_write(oft[fd].inode_no,&x);oft[fd].offset=off+(uint32_t)done;pthread_mutex_unlock(&meta);return (ssize_t)done;}
static int dir_empty(uint32_t n){inode_t x;inode_read(n,&x);for(uint32_t l=0;l<x.block_count;l++){int b=map_block(&x,l,0);if(b<0)continue;dir_entry_t e[16];disk_read((uint32_t)b,e);for(int j=0;j<16;j++)if(e[j].inode_no&&strcmp(e[j].name,".")&&strcmp(e[j].name,".."))return 0;}return 1;}
int fs_delete(const char *p,uint32_t cwd){pthread_mutex_lock(&meta);uint32_t n,par;char leaf[29];int r=resolve_path(p,cwd,&n,&par,leaf);if(r<0){pthread_mutex_unlock(&meta);return r;}if(n==0){pthread_mutex_unlock(&meta);return -EBUSY;}inode_t x;inode_read(n,&x);if(x.type==INODE_DIR&&!dir_empty(n)){pthread_mutex_unlock(&meta);return -ENOTEMPTY;}for(int i=0;i<10;i++)if(x.direct[i])free_block(x.direct[i]);if(x.indirect){uint32_t a[128];disk_read(x.indirect,a);for(int i=0;i<128;i++)if(a[i])free_block(a[i]);free_block(x.indirect);}dir_remove(par,leaf);free_inode(n);pthread_mutex_unlock(&meta);return 0;}
int fs_ls(const char *p,uint32_t cwd,char *out,size_t cap){if(!out||!cap)return -EINVAL;pthread_mutex_lock(&meta);uint32_t n;int r=resolve_path(p,cwd,&n,NULL,NULL);if(r<0){pthread_mutex_unlock(&meta);return r;}inode_t x;inode_read(n,&x);if(x.type!=INODE_DIR){pthread_mutex_unlock(&meta);return -ENOTDIR;}size_t used=0;out[0]=0;for(uint32_t l=0;l<x.block_count;l++){int b=map_block(&x,l,0);if(b<0)continue;dir_entry_t e[16];disk_read((uint32_t)b,e);for(int j=0;j<16;j++)if(e[j].inode_no&&strcmp(e[j].name,".")&&strcmp(e[j].name,"..")){inode_t child;inode_read(e[j].inode_no,&child);int k=snprintf(out+used,cap-used,"%s\t%s\t%u\n",e[j].name,child.type==INODE_DIR?"DIR":"FILE",child.size);if(k<0||(size_t)k>=cap-used){pthread_mutex_unlock(&meta);return -ENOSPC;}used+=(size_t)k;}}pthread_mutex_unlock(&meta);return (int)used;}
int fs_report(char *out,size_t cap){if(!out||!cap)return -EINVAL;pthread_mutex_lock(&meta);int freeb=count_free_blocks(),used=NUM_BLOCKS-DATA_START-freeb;unsigned long long bytes=0,files=0,allocated=0;int largest=0,run=0;unsigned char bm[512];disk_read(1,bm);for(int i=DATA_START;i<NUM_BLOCKS;i++){if(!(bm[i/8]&(1<<(i%8)))){run++;if(run>largest)largest=run;}else run=0;}for(int i=0;i<NUM_INODES;i++){inode_t x;inode_read(i,&x);if(x.type==INODE_FILE){files++;bytes+=x.size;allocated+=(unsigned long long)x.block_count*512;}}int k=snprintf(out,cap,"Blocks total: %u\nBlocks used: %d\nBlocks free: %d\nFiles: %llu\nInternal fragmentation (allocated file bytes - logical bytes): %llu\nExternal fragmentation indicator (largest free run / total free blocks): %d / %d\nDisk reads: %llu\nDisk writes: %llu\n",NUM_BLOCKS-DATA_START,used,freeb,files,allocated>=bytes?allocated-bytes:0,largest,freeb,(unsigned long long)disk_read_count(),(unsigned long long)disk_write_count());pthread_mutex_unlock(&meta);return k<0?-EIO:k;}
int fs_check(void){pthread_mutex_lock(&meta);unsigned char bm[512];disk_read(1,bm);unsigned char seen[NUM_BLOCKS]={0};for(int i=0;i<DATA_START;i++)seen[i]=1;for(int i=0;i<NUM_INODES;i++){inode_t x;inode_read(i,&x);if(x.type==INODE_FREE)continue;for(int j=0;j<10;j++)if(x.direct[j]){uint32_t b=x.direct[j];if(b<DATA_START||b>=NUM_BLOCKS||seen[b]){pthread_mutex_unlock(&meta);return -EUCLEAN;}seen[b]=1;}if(x.indirect){uint32_t b=x.indirect;if(b<DATA_START||b>=NUM_BLOCKS||seen[b]){pthread_mutex_unlock(&meta);return -EUCLEAN;}seen[b]=1;uint32_t a[128];disk_read(b,a);for(int j=0;j<128;j++)if(a[j]){b=a[j];if(b<DATA_START||b>=NUM_BLOCKS||seen[b]){pthread_mutex_unlock(&meta);return -EUCLEAN;}seen[b]=1;}}}for(int b=0;b<NUM_BLOCKS;b++)if(!!(bm[b/8]&(1u<<(b%8)))!=!!seen[b]){pthread_mutex_unlock(&meta);return -EUCLEAN;}pthread_mutex_unlock(&meta);return 0;}
